def classify_failure(exc: BaseException) -> tuple[str, str] | None:
    """Return a finite pair for a known exact class, else no classification.

    An unknown code never implies absence of a cause or lack of source/contact
    activity. The caller may apply a separately finite builtin-type fallback.
    """
    kind = type(exc)
    for expected, label, _path, _name, literals in _TYPE_ROWS:
        if kind is expected:
            args = _ARGS_DESCRIPTOR.__get__(exc)
            if (type(args) is not tuple or len(args) != 1
                    or type(args[0]) is not str
                    or len(args[0]) > MAX_ARGUMENT_CHARACTERS):
                return label, "unknown"
            return label, literals.get(args[0], "unknown")
    return None


__all__ = ("MAX_ARGUMENT_CHARACTERS", "SOURCE_PINS", "SOURCE_INVENTORY_SHA256",
           "classify_failure")
